      { kind: 'psalm', text: { en: "Let everything that has breath praise the LORD. Praise the LORD!", ar: "كُلُّ نَسَمَةٍ فَلْتُسَبِّحِ ٱلرَّبَّ. هَلِّلُويَا." }, label: { en: "6", ar: "6" } }
